    public void test_failingCloseActionStillClosesTypecheckingScope() throws Exception {
      initTestNodes();
      runWithinCommand(() -> {
        Assert.assertEquals("the application plugin installed the scoped typechecking provider", true, ScopedTypecheckingProvider.isInstalled());
        InterpreterSession session = InterpreterSession.open();
        TypecheckingSessionScope.joinSession(myProject.getRepository());
        boolean joined = TypecheckingSessionScope.current() != null;
        session.onClose(() -> {
          throw new IllegalStateException("close action failed");
        });
        String rethrown = null;
        try {
          session.close();
        } catch (IllegalStateException e) {
          rethrown = e.getMessage();
        }
        Assert.assertEquals("joinSession opens a typechecking scope in the session", true, joined);
        Assert.assertEquals("close() rethrows the failure of a close action", "close action failed", rethrown);
        Assert.assertEquals("the typechecking scope is closed although a close action registered after it failed", true, TypecheckingSessionScope.current() == null);
        Assert.assertEquals("the session is closed although a close action failed", true, InterpreterSession.current() == null);
      });
    }
